import React from "react";
import { render, fireEvent, screen, waitFor } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import Button from "../Button";
import * as stories from "./Tooltip.stories";
import Tooltip, { TooltipDelay } from ".";

const { Basic } = composeStories(stories) as any;

describe("Tooltip component", () => {
    it("shows tooltip on keyboard focus", async () => {
      render(
        <Tooltip label="Keyboard focus tooltip" data-testid="tooltip">
          <Button>label</Button>
        </Tooltip>
      );
      const target = screen.getByRole("button", { name: /label/i });
      target.focus();
      // default enter delay is 300ms
      await waitFor(
        () => {
          expect(screen.getByTestId("tooltip")).toBeTruthy();
        },
        { timeout: 350 }
      );
      target.blur();
      await waitFor(
        () => {
          expect(screen.queryByTestId("tooltip")).toBeFalsy();
        },
        { timeout: 350 }
      );
    });
  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    fireEvent.mouseEnter(screen.getByRole("button", { name: /Hover me/i }));
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props", async () => {
    render(
      <Tooltip placement="left" label="Lorem ipsum" data-testid="tooltip">
        <Button>label</Button>
      </Tooltip>
    );
    fireEvent.mouseEnter(screen.getByRole("button", { name: /label/i }));
    // default enter delay is 300ms
    await waitFor(
      () => {
        expect(screen.getByTestId("tooltip")).toBeTruthy();
      },
      { timeout: 350 }
    );
  });

  it("allow to set enter and exit delays", async () => {
    const { rerender } = render(
      <Tooltip
        label="Lorem ipsum"
        data-testid="tooltip"
        enterDelay={TooltipDelay.NONE}
        exitDelay={TooltipDelay.NONE}
      >
        <Button>label</Button>
      </Tooltip>
    );
    const target = screen.getByRole("button", { name: /label/i });

    fireEvent.mouseEnter(target);
    // should be visible immediately without async await
    expect(screen.getByTestId("tooltip")).toBeTruthy();
    fireEvent.mouseLeave(target);

    rerender(
      <Tooltip
        label="Lorem ipsum"
        data-testid="tooltip"
        enterDelay={TooltipDelay.LONG}
        exitDelay={TooltipDelay.LONG}
      >
        <Button>label</Button>
      </Tooltip>
    );

    fireEvent.mouseEnter(target);
    // long enter delay of 500ms
    expect(screen.queryByTestId("tooltip")).toBeFalsy();
    await waitFor(
      () => {
        expect(screen.queryByTestId("tooltip")).toBeFalsy();
      },
      { timeout: 350 }
    );
    await waitFor(
      () => {
        expect(screen.getByTestId("tooltip")).toBeTruthy();
      },
      { timeout: 550 }
    );

    fireEvent.mouseLeave(target);
    // long exit delay of 500ms
    expect(screen.getByTestId("tooltip")).toBeTruthy();
    await waitFor(
      () => {
        expect(screen.getByTestId("tooltip")).toBeTruthy();
      },
      { timeout: 350 }
    );
    await waitFor(
      () => {
        expect(screen.queryByTestId("tooltip")).toBeFalsy();
      },
      { timeout: 550 }
    );
  });
});
